head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF10910.xml';
scwin.threadID;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {

};
scwin.fn_SetHeader = function() {
    // CUD용 Header

};

// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_Grid.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_SetCode = function() {
    scwin.gLdMktTp = js_market;
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '4' || scwin.gLdMktTp == '6') {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, '9');
    }
    if (scwin.gLdMktTp == '1') {
        panel_jongmok.style.visibility = "";
        panel_isur.style.visibility = ""; // 상장신청인

    }

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 365); 	// 일주일전 날짜
    edt_FromDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 발행회사
    dts_CompanyList.DataID = "/DisclosureSearch.do?method=listCompanyCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_CompanyList.Reset();
    dts_Jongmok.DataID = "/DisclosureSearch.do?method=getJongmok" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&ISUR_CD=";
    dts_Jongmok.Reset();
};
scwin.fn_list_sync = function() {
    var url = "/MktActNotice.do?method=listTrdHaltReqAndAct" + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SDATE=" + $c.stf.getObjectValue(edt_FromDate) + "&EDATE=" + $c.stf.getObjectValue(edt_ToDate) + "&ISUR_CD=" + ($c.stf.getObjectValue(txb_isur_cd) == '' ? ($c.stf.getObjectValue(cmb_Company) == '' ? $c.stf.getObjectValue(txb_isur_cd2) : $c.stf.getObjectValue(cmb_Company)) : $c.stf.getObjectValue(txb_isur_cd)) + "&ISU_CD=" + $c.stf.getObjectValue(cmb_Jongmok) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_reload_auto = function() {
    scwin.stopReload();
    scwin.threadID = setInterval('fn_list_sync()', 30000); //30초
    scwin.fn_list_sync();
};
scwin.stopReload = function() {
    clearInterval(scwin.threadID);
};
scwin.getJongmok = function(gubun) {
    dts_Jongmok.DataID = "/DisclosureSearch.do?method=getJongmok" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R" + "&ISUR_CD=" + gubun;
    dts_Jongmok.Reset();
};
scwin.fn_clearJongmok = function() {
    $c.stf.setObjectValue(cmb_Company, '');
    $c.stf.setObjectValue(cmb_Jongmok, '');
};
scwin.fn_clearComAbbrv = function() {
    $c.stf.setObjectValue(txb_isur_cd, '');
    $c.stf.setObjectValue(txb_com_abbrv, '');
};


//상장신청인 clear
scwin.fn_clearIsurCd = function() {
    if (($c.stf.getObjectValue(txb_isur_cd) != '') || ($c.stf.getObjectValue(cmb_Company) != '')) {
        $c.stf.setObjectValue(txb_isur_cd2, '');
        $c.stf.setObjectValue(txb_isur_nm2, '');
    }
};




// dialog 호출용 함수
// 디지털증권 상장신청인 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = $c.stf.getObjectValue(txb_isur_cd2); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_isur_nm2); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_isur_cd2.setValue(arrPar[0].ISUR_CD);
        txb_isur_nm2.setValue(arrPar[0].ISUR_NM);
        scwin.fn_clearComAbbrv();
        scwin.fn_clearJongmok();
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_reload_auto();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (dts_Grid.errorMsg) {
        $c.win.alert(dts_Grid.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    scwin.fn_clearIsurCd(); // 상장신청인 

};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, '거래정지 요청 및 조치내역', '', 8);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_SetHeader();
    scwin.fn_init();
    scwin.fn_reload_auto();
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_Company_OnSelChange = function() {
    scwin.getJongmok($c.cp.valueOfIndex(cmb_Company, "VALUE", cmb_Company.getSelectedIndex()));
    scwin.fn_clearComAbbrv();
    scwin.fn_clearIsurCd();
};
scwin.cmb_Jongmok_OnSelChange = function() {
    scwin.fn_clearComAbbrv();
    scwin.fn_clearIsurCd();
};
scwin.txb_isur_cd2_onchange = function() {
    $c.stf.setObjectValue(txb_isur_nm2, '');
};
scwin.img_isur_cd_onclick = function() {
    fn_GetPar = fn_GetParIsur;
    fn_SetPar = fn_SetParIsur;
    $c.lcd.fn_PopFindDigitalIsurAll();
};
